begin;
create function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'assertion failed: %',message; end if; end $$;
create function pg_temp.expect_error(command text,expected text) returns void language plpgsql as $$declare actual text; begin begin execute command; exception when others then get stacked diagnostics actual=returned_sqlstate; end; if actual is distinct from expected then raise exception 'expected %, got % for %',expected,actual,command; end if; end $$;
insert into auth.users(id) values('27120000-0000-4000-8000-000000000001'),('27120000-0000-4000-8000-000000000002'),('27120000-0000-4000-8000-000000000003');
insert into public.user_roles(user_id,role) values('27120000-0000-4000-8000-000000000001','professional'),('27120000-0000-4000-8000-000000000003','professional') on conflict do nothing;
insert into public.professional_student_relationships(professional_user_id,student_user_id,status) values('27120000-0000-4000-8000-000000000001','27120000-0000-4000-8000-000000000002','active');
set local role authenticated;
select set_config('request.jwt.claim.sub','27120000-0000-4000-8000-000000000002',true);
select public.save_athlete_plan(0,'weekly','{"week":{"1":"27120000-0000-4000-8000-000000000010"},"dayPlan":{}}','[{"id":"27120000-0000-4000-8000-000000000010","title":"Meu ABC","prescription":{"ex":[{"id":"squat","sets":3,"reps":10,"weight":20}]}}]');
select set_config('request.jwt.claim.sub','27120000-0000-4000-8000-000000000001',true);
select public.save_student_plan_draft('27120000-0000-4000-8000-000000000002','Hipertrofia','{"routines":[{"id":"r","name":"Treino A","ex":[{"id":"squat","sets":4,"reps":8,"weight":80,"rest":90,"rir":2,"notes":"Controle"}]}],"week":{"1":"r"},"dayPlan":{},"planMode":"weekly"}',0);
select pg_temp.assert_true((select count(*)=1 from public.professional_plan_drafts),'draft persisted');
select set_config('request.jwt.claim.sub','27120000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.professional_plan_drafts),'student cannot read private draft');
select pg_temp.assert_true((select count(*)=0 from public.athlete_plan_library),'draft does not deliver');
select pg_temp.assert_true((select title='Meu ABC' from public.athlete_routines),'draft does not alter active plan');
select set_config('request.jwt.claim.sub','27120000-0000-4000-8000-000000000003',true);
select pg_temp.expect_error($cmd$select public.save_student_plan_draft('27120000-0000-4000-8000-000000000002','Intruso','{"routines":[],"week":{}}',0)$cmd$,'42501');
select pg_temp.expect_error($cmd$select public.send_student_plan('27120000-0000-4000-8000-000000000002',1)$cmd$,'42501');
select set_config('request.jwt.claim.sub','27120000-0000-4000-8000-000000000001',true);
select public.send_student_plan('27120000-0000-4000-8000-000000000002',1);
select public.send_student_plan('27120000-0000-4000-8000-000000000002',1);
select pg_temp.assert_true((select count(*)=1 from public.program_versions),'send retry is idempotent');
select pg_temp.expect_error($cmd$select public.save_student_plan_draft('27120000-0000-4000-8000-000000000002','Stale','{"routines":[],"week":{}}',0)$cmd$,'40001');
select set_config('request.jwt.claim.sub','27120000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=1 from public.athlete_plan_library),'received in library');
select pg_temp.assert_true((select count(*)=0 from public.athlete_plan_selection),'delivery does not select');
select pg_temp.assert_true((select title='Meu ABC' from public.athlete_routines),'delivery preserves execution plan');
select public.apply_library_plan((select id from public.athlete_plan_library where source_type='professional'));
select pg_temp.assert_true((select count(*)=1 from public.athlete_plan_library where source_type='self'),'personal plan captured before applying');
select pg_temp.assert_true((select prescription->'ex'->0->>'weight'='80' from public.athlete_routines where prescription->>'assigned'='true'),'execution uses selected prescription');
select public.start_workout_execution('27120000-0000-4000-8000-000000000020',(select assignment_id from public.athlete_plan_library where source_type='professional'),'monday');
select pg_temp.assert_true((select prescription_snapshot->'exercises'->0->>'load'='80' from public.workout_executions),'historical snapshot captured');
select public.apply_library_plan((select id from public.athlete_plan_library where source_type='self'));
select pg_temp.assert_true((select title='Meu ABC' from public.athlete_routines),'personal plan restored');
select pg_temp.assert_true((select count(*)=2 from public.athlete_plan_library),'both plans retained');
select set_config('request.jwt.claim.sub','27120000-0000-4000-8000-000000000001',true);
select public.save_student_plan_draft('27120000-0000-4000-8000-000000000002','Hipertrofia','{"routines":[{"id":"r","name":"Treino A","ex":[{"id":"squat","sets":4,"reps":8,"weight":90}]}],"week":{"1":"r"},"dayPlan":{},"planMode":"weekly"}',1);
select public.send_student_plan('27120000-0000-4000-8000-000000000002',2);
select set_config('request.jwt.claim.sub','27120000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select title='Meu ABC' from public.athlete_routines),'updated delivery does not switch back from personal');
select pg_temp.assert_true((select count(*)=3 from public.athlete_plan_library),'old and new versions remain available');
select public.apply_library_plan((select l.id from public.athlete_plan_library l join public.program_assignments a on a.id=l.assignment_id join public.program_versions v on v.id=a.version_id order by v.version_number desc limit 1));
select pg_temp.assert_true((select prescription->'ex'->0->>'weight'='90' from public.athlete_routines where prescription->>'assigned'='true'),'new version explicitly selected');
select pg_temp.assert_true((select prescription_snapshot->'exercises'->0->>'load'='80' from public.workout_executions),'old snapshot unchanged');
select pg_temp.expect_error($cmd$select public.save_athlete_plan(4,'weekly','{}','[]')$cmd$,'42501');
select set_config('request.jwt.claim.sub','27120000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=0 from public.athlete_plan_library),'other account cannot read library');
select pg_temp.expect_error($cmd$update public.athlete_plan_library set title='forged'$cmd$,'42501');
select set_config('request.jwt.claim.sub','27120000-0000-4000-8000-000000000001',true);
select public.save_student_plan_draft('27120000-0000-4000-8000-000000000002','Empty','{"routines":[],"week":{}}',2);
select pg_temp.expect_error($cmd$select public.send_student_plan('27120000-0000-4000-8000-000000000002',3)$cmd$,'22023');
select pg_temp.assert_true((select count(*)=2 from public.program_versions),'failed send leaves no partial version');
select pg_temp.assert_true((select sent_revision=2 from public.professional_plan_drafts),'failed send does not mark draft as sent');
select pg_temp.expect_error($cmd$select public.send_student_plan('27120000-0000-4000-8000-000000000002',null)$cmd$,'22023');
rollback;
